util.debugFunc(() => {
    java.log(`DEBUG = ${util.settings.DEBUG}\n`)
    java.log(JSON.stringify(util.settings, null, 4))
    java.log(`${getWebViewUA()}\n`)
    java.log(`${cache.get("csfrToken")}\n`)
